import { test, expect } from '@playwright/test';

test('requester name can be filled', async ({ page }) => {
  await page.goto('/login');
  const form = page.locator('.login-page form');
  await form.locator('input:not([type="password"])').fill('aayush');
  await form.locator('input[type="password"]').fill('correct-horse');
  await form.locator('button[type="submit"]').click();
  await page.waitForURL('**/dashboard/devices');
  await page.goto('/dashboard/provisioning');
  await page.getByTestId('provisioning-requester-name').fill('A. Ramirez');
  await expect(page.getByTestId('provisioning-requester-name')).toHaveValue('A. Ramirez');
});
